// 组装致远工作台：把 vendor/ 下的三份 Client 代码拼进一个 bundle。
import fs from 'node:fs'
import path from 'node:path'

const HERE = path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1'))
const VENDOR = path.join(HERE, 'vendor')

const header = [
  '/* dsh-seeyon-workbench — generated by build.mjs, do not edit */',
  ';(function () {',
  '  if (!window.__ModuleLoader__) return',
  '  var REAL = window.__ModuleLoader__.load.bind(window.__ModuleLoader__)',
  "  var OUR_ID = 'dsh-seeyon-workbench'",
  '  var VENDORS = {}',
  "  var CAPTURE = ['@local/dsh-seeyon-todo', '@local/dsh-skillhub', '@local/dsh-vpn']",
  '  window.__ModuleLoader__.load = function (def) {',
  '    if (def && def.id && CAPTURE.indexOf(def.id) >= 0) {',
  '      if (!VENDORS[def.id]) VENDORS[def.id] = def',
  '      return undefined',
  '    }',
  '    return REAL(def)',
  '  }',
  '  window.__DSH_WORKBENCH__ = { vendors: VENDORS, load: REAL, require: null }',
  '})()',
  '',
].join('\n')

const parts = [header]
for (const entry of fs.readdirSync(VENDOR, { withFileTypes: true })) {
  if (!entry.isDirectory()) continue
  const file = path.join(VENDOR, entry.name, 'client.js')
  if (!fs.existsSync(file)) continue
  parts.push('/* ---- vendor: ' + entry.name + ' ---- */')
  parts.push(fs.readFileSync(file, 'utf8').replace(/^\uFEFF/, ''))
  parts.push(';\n')
}
parts.push('/* ---- workbench ui ---- */')
parts.push(fs.readFileSync(path.join(HERE, 'src', 'ui.js'), 'utf8'))

const out = path.join(HERE, 'client.js')
fs.writeFileSync(out, parts.join('\n'), 'utf8')
console.log('built client.js', fs.statSync(out).size, 'bytes')
